import React, { CSSProperties } from 'react';

import {
  SegmentedControlImage,
  SegmentedControlImageSlot,
  SegmentedControlItem,
  SegmentedControlLabel,
  SegmentedControlRoot,
} from './SegmentedControl.styles';

export interface SegmentedControlOption {
  value: string;
  label?: React.ReactNode;
  imageSrc?: string;
  imageAlt?: string;
  image?: React.ReactNode;
}

export interface SegmentedControlProps {
  options: SegmentedControlOption[];
  value: string;
  onValueChange: (value: string) => void;
  ariaLabel?: string;
  dataTestId?: string;
  css?: CSSProperties;
}

const renderOptionImage = (
  option: SegmentedControlOption,
  isSelected: boolean,
) => {
  if (option.image) {
    return (
      <SegmentedControlImageSlot $isSelected={isSelected}>
        {option.image}
      </SegmentedControlImageSlot>
    );
  }

  if (option.imageSrc) {
    return (
      <SegmentedControlImage
        $isSelected={isSelected}
        src={option.imageSrc}
        alt={option.imageAlt ?? ''}
        aria-hidden
      />
    );
  }

  return null;
};

export const SegmentedControl: React.FC<SegmentedControlProps> = ({
  options,
  value,
  onValueChange,
  ariaLabel,
  dataTestId,
  css,
}) => {
  return (
    <SegmentedControlRoot
      role="radiogroup"
      aria-label={ariaLabel}
      data-testid={dataTestId}
      style={css}
    >
      {options.map((option) => {
        const isSelected = option.value === value;

        return (
          <SegmentedControlItem
            key={option.value}
            type="button"
            role="radio"
            aria-checked={isSelected}
            $isSelected={isSelected}
            onClick={() => {
              if (option.value !== value) {
                onValueChange(option.value);
              }
            }}
            data-testid={
              dataTestId ? `${dataTestId}-option-${option.value}` : undefined
            }
          >
            <SegmentedControlLabel>
              {renderOptionImage(option, isSelected)}
              {option.label}
            </SegmentedControlLabel>
          </SegmentedControlItem>
        );
      })}
    </SegmentedControlRoot>
  );
};
